sections.syntax:
-- Toutes les colonnes :
SELECT * FROM nom_table;

-- Colonnes spécifiques :
SELECT colonne1, colonne2 FROM nom_table;

SELECT colonne1, colonne2
FROM nom_table
WHERE condition;

examples.code:
SELECT name, age
FROM Students
WHERE age > 21;

SELECT name, age, email
FROM Students
WHERE age >= 18 AND age <= 25;

SELECT product_name, price
FROM Products
WHERE price BETWEEN 10 AND 100;

sections.syntax:
SELECT colonne1, colonne2
FROM nom_table
ORDER BY colonne1 [ASC|DESC], colonne2 [ASC|DESC];

examples.code:
SELECT name, age
FROM Students
ORDER BY age ASC;

SELECT product_name, price
FROM Products
ORDER BY price DESC;

SELECT name, department, salary
FROM Employees
ORDER BY department ASC, salary DESC;

SELECT DISTINCT city, country
FROM Customers
ORDER BY country, city;

sections.syntax:
-- Alias de colonne :
SELECT nom_colonne AS nom_alias FROM table;

-- Alias de table :
SELECT t.colonne FROM nom_table AS t;

SELECT colonne, FONCTION_AGGRÉGATION(autre_colonne)
FROM nom_table
GROUP BY colonne;

examples.code:
SELECT name, age
FROM Students
WHERE age > (SELECT AVG(age) FROM Students);

SELECT product_name
FROM Products
WHERE product_id NOT IN (
  SELECT DISTINCT product_id FROM OrderItems
);
